// Simple circuit breaker (pseudo)
class CircuitBreaker {
  constructor(threshold) { this.open = false; this.failures = 0; this.threshold = threshold; }
  onFailure() { this.failures++; if (this.failures > this.threshold) this.open = true; }
  allow() { return !this.open; }
}
```

